#include<bits/stdc++.h>
#define REP(i,s,t) for(int i=s;i<=t;i++)
using namespace std;
const int Mod=1e9+7;
int power(int b,int e){
	if(!e) return 1;
	int tmp=power(b,e>>1);
	tmp=1ll*tmp*tmp%Mod;
	if(e&1) tmp=1ll*tmp*b%Mod;
	return tmp; 
}
vector<int> com;
int p[10][10],f[1<<20],g[1<<20];
int main(){
	int n; cin>>n;
	REP(i,0,n-1) REP(j,0,n-1){
		int per; cin>>per;
		p[i][j]=1ll*per*power(100,Mod-2)%Mod;
	}
	REP(i,n,5) p[i][i]=1;
	REP(i,0,63){
		int cnt=0;
		REP(j,0,5) if(i&1<<j) cnt++;
		if(cnt==3) com.push_back(i);
	}
	REP(i,0,(1<<18)-1){
		bool b[6][6]={0};
		int tmp=0,mask=0,pos=1;
		REP(j,0,5) REP(k,0,2){
			if(i&1<<tmp) b[j][k]=true,pos=1ll*pos*p[j][k]%Mod;
			else pos=1ll*pos*(1-p[j][k]+Mod)%Mod;
			tmp++;
		}
		REP(j,0,19){
			int p[3],p_cnt=0;
			REP(k,0,5) if(com[j]&1<<k) p[p_cnt++]=k;
			int p1=p[0],p2=p[1],p3=p[2];
			if(b[p1][0]&&b[p2][1]&&b[p3][2]||b[p1][0]&&b[p2][2]&&b[p3][1]||
			   b[p1][1]&&b[p2][0]&&b[p3][2]||b[p1][1]&&b[p2][2]&&b[p3][0]||
			   b[p1][2]&&b[p2][0]&&b[p3][1]||b[p1][2]&&b[p2][1]&&b[p3][0]) mask|=1<<j;
		}
		f[mask]=(f[mask]+pos)%Mod;
	}
	REP(i,0,(1<<18)-1){
		bool b[6][6]={0};
		int tmp=0,mask=0,pos=1;
		REP(j,0,5) REP(k,3,5){
			if(i&1<<tmp) b[j][k]=true,pos=1ll*pos*p[j][k]%Mod;
			else pos=1ll*pos*(1-p[j][k]+Mod)%Mod;
			tmp++;
		}
		REP(j,0,19){
			int p[3],p_cnt=0,s=com[j]^63;
			REP(k,0,5) if(s&1<<k) p[p_cnt++]=k;
			int p1=p[0],p2=p[1],p3=p[2];
			if(b[p1][3]&&b[p2][4]&&b[p3][5]||b[p1][3]&&b[p2][5]&&b[p3][4]||
			   b[p1][4]&&b[p2][3]&&b[p3][5]||b[p1][4]&&b[p2][5]&&b[p3][3]||
			   b[p1][5]&&b[p2][3]&&b[p3][4]||b[p1][5]&&b[p2][4]&&b[p3][3]) mask|=1<<j;
		}
		g[mask]=(g[mask]+pos)%Mod;
	}
	REP(i,0,19) for(int j=(1<<20)-1;j>=0;j--) if(j&1<<i) g[j]=(g[j]+g[j^1<<i])%Mod;
	int ans=0;
	REP(i,0,(1<<20)-1) ans=(ans+1ll*f[i]*g[(1<<20)-1^i])%Mod;
	cout<<(1-ans+Mod)%Mod<<endl;
	return 0;
}
